/* Format-specific tools: spreadsheet cells, document/slide text and image transforms. */
(() => {
  const el=(tag,cls,text)=>{const n=document.createElement(tag);if(cls)n.className=cls;if(text!==undefined)n.textContent=text;return n;};
  const api=async(path,data)=>{const r=await fetch('/api/'+path,data===undefined?{}:{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});const d=await r.json();if(!r.ok)throw Error(d.detail||'The document action failed.');return d;};
  const button=(label,action,parent)=>{const n=el('button','workspace-button',label);n.type='button';n.onclick=async()=>{try{await action();}catch(error){VisionWorkspace.notify(error);}};parent.append(n);return n;};
  const formats=/\.(xlsx|xlsm|xltx|xltm|xls|xlsb|ods|csv|tsv|docx|odt|pptx|png|jpe?g|webp|bmp|tiff?|gif|ico|avif|heic|heif)$/i;
  async function open(file,ctx){
    const {body,bar,status,alive,mark,saved}=ctx,loading=el('p','workspace-editor-loading','Opening editing tools…');body.append(loading);
    try{const data=await api('document-edit/'+file.id);if(!alive())return;loading.remove();
      if(data.kind==='sheet')return sheetEditor(file,data,ctx);
      if(data.kind==='image')return imageEditor(file,data,ctx);
      return paragraphEditor(file,data,ctx);
    }catch(error){if(alive()){loading.textContent=error.message;status.textContent='Preview remains available';}}
  }
  function saveButton(file,data,ctx,payload){const save=button('Save edited copy',async()=>{save.disabled=true;try{const result=await api('document-edit/'+file.id,{revision:data.revision,...payload()});ctx.saved();await VisionWorkspace.selectFile(result,{edit:true});}finally{save.disabled=false;}},ctx.bar);return save;}
  function sheetEditor(file,initial,ctx){
    const {body,bar,status,alive,mark}=ctx,changes=new Map(),tools=el('div','workspace-sheet-tools'),sheet=el('select'),position=el('span','workspace-page-label'),wrap=el('div','workspace-table-scroll');let current=initial,request=0;
    sheet.setAttribute('aria-label','Worksheet');for(const name of initial.sheets)sheet.append(new Option(name,name));sheet.value=initial.sheet;tools.append(sheet);
    const prev=button('Previous rows',()=>load(current.sheet,Math.max(0,current.offset-150)),tools),next=button('Next rows',()=>load(current.sheet,current.offset+150),tools);tools.append(position);body.append(tools);
    if(initial.converted)body.append(el('p','workspace-editor-format-note','Saves a new .xlsx workbook containing sheet values and your edits. Legacy formatting, formulas, charts and macros are not preserved during this conversion.'));
    else if(/\.ods$/i.test(file.name))body.append(el('p','workspace-editor-format-note','Edited ODS cells are saved as text. Other stored cells and formatting are preserved.'));
    body.append(wrap);const key=(name,row,column)=>name+'\u0000'+row+'\u0000'+column;
    function render(data){current=data;sheet.value=data.sheet;sheet.dispatchEvent(new Event('vision:selection-sync'));prev.disabled=!data.offset;next.disabled=!data.more;position.textContent='Rows '+(data.offset+1)+'–'+(data.offset+data.rows.length);const table=el('table','workspace-table workspace-editable-sheet'),head=el('thead'),tr=el('tr');tr.append(el('th','',''));const count=Math.max(1,...data.rows.map(r=>r.length));for(let c=0;c<count;c++){let x=c+1,name='';while(x){x--;name=String.fromCharCode(65+x%26)+name;x=Math.floor(x/26);}tr.append(el('th','',name));}head.append(tr);table.append(head);const tbody=el('tbody');const rows=data.rows.length?data.rows:[['']];for(let r=0;r<rows.length;r++){const row=el('tr');row.append(el('th','row-number',data.offset+r+1));for(let c=0;c<count;c++){const cell=el('td'),field=el('input','workspace-cell-input'),id=key(data.sheet,data.offset+r,c);field.value=changes.has(id)?changes.get(id).value:rows[r][c]??'';field.setAttribute('aria-label',data.sheet+' row '+(data.offset+r+1)+' column '+(c+1));field.oninput=()=>{changes.set(id,{sheet:data.sheet,row:data.offset+r,column:c,value:field.value});cell.classList.add('changed');mark();};cell.append(field);row.append(cell);}tbody.append(row);}table.append(tbody);wrap.replaceChildren(table);}
    async function load(name,offset){const version=++request;status.textContent='Loading rows…';const data=await api('document-edit/'+file.id+'?sheet='+encodeURIComponent(name)+'&offset='+offset);if(!alive()||version!==request)return;if(data.revision!==initial.revision)throw Error('This workbook changed. Reopen the editor before continuing.');render(data);status.textContent=changes.size?changes.size+' changed cells':'';}
    sheet.onchange=()=>load(sheet.value,0).catch(VisionWorkspace.notify);render(initial);saveButton(file,initial,ctx,()=>({cells:[...changes.values()]}));
  }
  function paragraphEditor(file,initial,ctx){
    const {body,bar,status,alive,mark}=ctx,presentation=initial.kind==='presentation',changes=new Map(),layout=el('div',presentation?'workspace-slide-editor':'workspace-paragraph-editor'),content=el('div','workspace-paragraph-fields'),preview=el('div','workspace-slide-editor-preview');let current=initial,slide=0,request=0;
    if(presentation){const tools=el('div','workspace-sheet-tools');const prev=button('Previous slide',()=>load(slide-1),tools),next=button('Next slide',()=>load(slide+1),tools),label=el('span','workspace-page-label');tools.append(label);body.append(tools);layout.append(preview);function update(){prev.disabled=slide===0;next.disabled=slide>=current.preview.count-1;label.textContent='Slide '+(slide+1)+' of '+current.preview.count;}current._update=update;}
    layout.append(content);body.append(el('p','workspace-editor-format-note','Edit text while keeping the document structure and embedded images. Changed paragraphs use their first text style; layout may reflow. Save keeps the original.'));body.append(layout);
    function render(data){content.replaceChildren();if(presentation){preview.replaceChildren();const stage=el('div','workspace-slide');stage.style.aspectRatio=data.preview.ratio||16/9;for(const shape of data.preview.shapes){const n=el(shape.kind==='image'?'img':'div','workspace-slide-'+shape.kind);Object.assign(n.style,{left:shape.x+'%',top:shape.y+'%',width:shape.w+'%',height:shape.h+'%'});if(shape.kind==='image'){n.src=shape.url;n.alt='Slide image';}else n.textContent=shape.text||'';stage.append(n);}preview.append(stage);initial._update();}
      for(const paragraph of data.paragraphs){const label=el('label','workspace-paragraph-field'),field=el('textarea');const id=slide+':'+paragraph.id;label.append(el('span','',presentation?'Text '+(paragraph.id+1):'Paragraph '+(paragraph.id+1)));field.value=changes.get(id)?.text??paragraph.text;field.rows=Math.min(8,Math.max(2,Math.ceil(field.value.length/75)));field.oninput=()=>{changes.set(id,{slide,id:paragraph.id,text:field.value});mark();};label.append(field);content.append(label);}
    }
    async function load(index){if(index<0||index>=current.preview.count)return;const version=++request;const data=await api('document-edit/'+file.id+'?slide='+index);if(!alive()||version!==request)return;if(data.revision!==initial.revision)throw Error('This presentation changed. Reopen its editor.');slide=index;current=data;render(data);}
    render(initial);saveButton(file,initial,ctx,()=>{const sections=new Map();for(const change of changes.values()){if(!sections.has(change.slide))sections.set(change.slide,{slide:change.slide,paragraphs:[]});sections.get(change.slide).paragraphs.push({id:change.id,text:change.text});}return {sections:[...sections.values()]};});
  }
  function imageEditor(file,data,ctx){
    const {body,mark}=ctx,layout=el('div','workspace-image-editor'),stage=el('div','workspace-image-stage'),canvas=el('canvas','workspace-image-canvas'),tools=el('aside','workspace-document-tools');stage.append(canvas);layout.append(stage,tools);body.append(layout);tools.append(el('h3','','Image tools'),el('p','',data.width+' × '+data.height+' pixels. Crop uses original image coordinates. Edits export as PNG.'+(data.frames>1?' This editor changes the first frame only.':'')));
    const image=new Image();image.onload=draw;image.onerror=()=>VisionWorkspace.notify(Error('This image cannot be decoded for editing.'));image.src='/api/workspace/'+file.id+'/image';
    const controls={};function number(name,label,value,min=0,max=16000,step=1){const row=el('label','workspace-image-field');row.append(el('span','',label));const input=el('input');input.type='number';input.min=min;input.max=max;input.step=step;input.value=value;input.oninput=()=>{if(['w','h'].includes(name)&&controls.outputWidth){controls.outputWidth.value=rotation%180?controls.h.value:controls.w.value;controls.outputHeight.value=rotation%180?controls.w.value:controls.h.value;}mark();draw();};row.append(input);tools.append(row);controls[name]=input;return input;}
    number('x','Crop left',0,0,data.width);number('y','Crop top',0,0,data.height);number('w','Crop width',data.width,1,data.width);number('h','Crop height',data.height,1,data.height);let rotation=0,flip=false;
    const rotated=el('span','workspace-preview-note','Rotation: 0°');tools.append(rotated);button('Rotate 90°',()=>{rotation=(rotation+90)%360;rotated.textContent='Rotation: '+rotation+'°';const width=controls.outputWidth.value;controls.outputWidth.value=controls.outputHeight.value;controls.outputHeight.value=width;mark();draw();},tools);button('Flip horizontal',()=>{flip=!flip;mark();draw();},tools);
    number('outputWidth','Output width',data.width,1,16000);number('outputHeight','Output height',data.height,1,16000);number('brightness','Brightness',1,0,3,.05);number('contrast','Contrast',1,0,3,.05);
    const value=name=>Number(controls[name].value);function payload(){return {crop:[value('x'),value('y'),value('w'),value('h')],rotation,flip,resize:[value('outputWidth'),value('outputHeight')],brightness:value('brightness'),contrast:value('contrast')};}
    function draw(){if(!image.complete||!image.naturalWidth||!controls.outputWidth||value('w')<1||value('h')<1)return;const width=Math.max(1,value('outputWidth')),height=Math.max(1,value('outputHeight')),scale=Math.min(1,1400/Math.max(width,height));canvas.width=Math.max(1,Math.round(width*scale));canvas.height=Math.max(1,Math.round(height*scale));const context=canvas.getContext('2d');context.clearRect(0,0,canvas.width,canvas.height);context.filter='brightness('+value('brightness')+') contrast('+value('contrast')+')';context.save();context.translate(canvas.width/2,canvas.height/2);if(flip)context.scale(-1,1);context.rotate(rotation*Math.PI/180);const sideways=rotation%180!==0,w=sideways?canvas.height:canvas.width,h=sideways?canvas.width:canvas.height;context.drawImage(image,value('x')/data.width*image.naturalWidth,value('y')/data.height*image.naturalHeight,value('w')/data.width*image.naturalWidth,value('h')/data.height*image.naturalHeight,-w/2,-h/2,w,h);context.restore();}
    saveButton(file,data,ctx,payload);
  }
  window.VisionDocumentEditors={supports:file=>formats.test(file.name),open};
})();
